export function plainText(html){const template=document.createElement('template');template.innerHTML=String(html);const doc=template.content;doc.querySelectorAll('script,style,iframe,object,embed').forEach(el=>el.remove());doc.querySelectorAll('br').forEach(el=>el.replaceWith('\n'));doc.querySelectorAll('p,div,li').forEach(el=>el.append('\n'));return (doc.textContent||'').replace(/\[sound:[^\]]*\]/g,'').trim();}
export async function readAnki(file){if(file.size>25*1024*1024)throw new Error('Choose a deck smaller than 25 MB.');const buffer=await file.arrayBuffer();const hash=Array.from(new Uint8Array(await crypto.subtle.digest('SHA-256',buffer)),x=>x.toString(16).padStart(2,'0')).join('');const worker=new Worker(new URL('./anki-worker.js',import.meta.url),{type:'module'});const parsed=await new Promise((resolve,reject)=>{const timer=setTimeout(()=>{worker.terminate();reject(new Error('Import timed out. Try a smaller text export.'));},30000);worker.onmessage=e=>{clearTimeout(timer);worker.terminate();e.data.error?reject(new Error(e.data.error)):resolve(e.data);};worker.onerror=()=>{clearTimeout(timer);worker.terminate();reject(new Error('Unable to read the deck. Try Anki’s Notes in Plain Text export.'));};worker.postMessage({buffer,name:file.name},[buffer]);});if(!parsed.notes.length)throw new Error('This deck has no notes.');return {id:'personal-'+hash,name:file.name.replace(/\.(apkg|tsv|txt)$/i,''),notes:parsed.notes};}
export function makeCards(pending,frontField,backField){const cards=[];let skipped=0;for(const note of pending.notes){const front=plainText(note.fields[frontField]||''),back=plainText(note.fields[backField]||'');const clozes=[...new Set(Array.from(front.matchAll(/\{\{c(\d+)::([\s\S]*?)\}\}/g),m=>m[1]))];if(clozes.length){for(const n of clozes){const rendered=front.replace(/\{\{c(\d+)::([\s\S]*?)\}\}/g,(_,num,value)=>num===n?'['+(value.split('::')[1]||'…')+']':value.split('::')[0]);const answer=front.replace(/\{\{c\d+::([\s\S]*?)\}\}/g,(_,value)=>value.split('::')[0])+(back?'\n\n'+back:'');cards.push({id:pending.id+'-'+note.id+'-c'+n,front:rendered,answer});}}else if(front&&back)cards.push({id:pending.id+'-'+note.id,front,answer:back});else skipped++;}if(cards.length>10000)throw new Error('Maximum 10,000 personal cards.');return {cards,skipped};}
